export const grades={sunset:'Sunset',neon:'Neon night',gold:'Palm gold',teal:'Teal dusk',mono:'Ink mono',plain:'Plain'};
export function photoFilter(grade){return {sunset:'saturate(1.15) contrast(1.17) sepia(.24)',neon:'saturate(1.2) contrast(1.25) hue-rotate(310deg)',gold:'sepia(.28) saturate(1.1) contrast(1.15)',teal:'saturate(.75) contrast(1.13) hue-rotate(15deg)',mono:'grayscale(1) contrast(1.4)',plain:'none'}[grade];}
export function tintPanel(c,x,y,w,h,grade){if(grade==='plain')return;c.save();c.globalCompositeOperation='soft-light';let g=c.createLinearGradient(x,y,x+w,y+h);const colors={sunset:['#ffb060','#9b357f'],gold:['#f4b664','#b94d45'],neon:['#00a6a6','#dc438c'],teal:['#478a93','#183548'],mono:['#d8b77b','#777777']}[grade];g.addColorStop(0,colors[0]);g.addColorStop(1,colors[1]);c.fillStyle=g;c.globalAlpha=.55;c.fillRect(x,y,w,h);c.restore();}
export function finishEffects(c,w,h,s){if(s.vignette){let v=c.createRadialGradient(w*.52,h*.43,w*.2,w*.5,h*.5,Math.max(w,h)*.72);v.addColorStop(0,'#0000');v.addColorStop(1,'#101223aa');c.fillStyle=v;c.fillRect(0,0,w,h);}if(s.texture){c.save();c.fillStyle='#1b1720';c.globalAlpha=.095;const step=Math.max(5,w/250);for(let y=0;y<h;y+=step)for(let x=0;x<w;x+=step){c.beginPath();c.arc(x+(Math.floor(y/step)%2)*step/2,y,step*.17,0,7);c.fill();}c.restore();}}
